  "inlineSchema": "// ------------------------------------------------------\n// Konfigurasi Client & Database Server\n// ------------------------------------------------------\ngenerator client {\n  provider   = \"prisma-client-js\"\n  engineType = \"binary\"\n}\n\ndatasource db {\n  provider  = \"postgresql\"\n  url       = env(\"DATABASE_URL\")\n  directUrl = env(\"DIRECT_URL\")\n}\n\n// ------------------------------------------------------\n// ENUMS (Pilihan Statis)\n// ------------------------------------------------------\nenum Role {\n  ADMIN_KANTOR\n  PROJECT_MANAGER\n  SITE_ENGINEER\n  MANDOR\n}\n\nenum StatusApproval {\n  PENDING\n  APPROVED\n  REJECTED\n}\n\nenum IssueSeverity {\n  LOW\n  MEDIUM\n  HIGH\n  CRITICAL\n}\n\n// ------------------------------------------------------\n// TABEL DATABASE UTAMA\n// ------------------------------------------------------\n\n// 1. Data Pengguna & Role\nmodel User {\n  id               String            @id @default(uuid())\n  name             String\n  email            String            @unique\n  role             Role\n  createdAt        DateTime          @default(now())\n  dailyReports     DailyReport[]\n  materialRequests MaterialRequest[]\n  issues           Issue[]\n  comments         Comment[]\n  activityLogs     ActivityLog[]\n}\n\n// 2. Data Proyek\nmodel Project {\n  id               String            @id @default(uuid())\n  title            String\n  description      String?\n  location         String\n  startDate        DateTime\n  endDate          DateTime\n  status           String            @default(\"ON_PROGRESS\") // ON_PROGRESS, COMPLETED, HOLD\n  createdAt        DateTime          @default(now())\n  workItems        WorkItem[]\n  dailyReports     DailyReport[]\n  materialRequests MaterialRequest[]\n  issues           Issue[]\n}\n\n// 3. Progress per Item Pekerjaan\nmodel WorkItem {\n  id             String        @id @default(uuid())\n  projectId      String\n  project        Project       @relation(fields: [projectId], references: [id])\n  itemName       String // Contoh: \"Pengecoran Kolom Lt. 1\"\n  unit           String // Contoh: \"m3\", \"m2\", \"unit\"\n  targetQuantity Float\n  weightPercent  Float // Bobot persen proyek (misal: 15%)\n  progressLogs   ProgressLog[]\n}\n\n// 4. Laporan Harian (Daily Report) & Approval\nmodel DailyReport {\n  id           String         @id @default(uuid())\n  projectId    String\n  project      Project        @relation(fields: [projectId], references: [id])\n  reporterId   String\n  reporter     User           @relation(fields: [reporterId], references: [id])\n  date         DateTime       @default(now())\n  weather      String // Cerah, Hujan, dll.\n  notes        String?\n  status       StatusApproval @default(PENDING)\n  approvedBy   String?\n  approvedAt   DateTime?\n  createdAt    DateTime       @default(now())\n  progressLogs ProgressLog[]\n  comments     Comment[]\n}\n\n// 5. Upload Foto/Video Progres & Progress Detail\nmodel ProgressLog {\n  id            String      @id @default(uuid())\n  dailyReportId String\n  dailyReport   DailyReport @relation(fields: [dailyReportId], references: [id])\n  workItemId    String\n  workItem      WorkItem    @relation(fields: [workItemId], references: [id])\n  quantityDone  Float\n  mediaUrls     String[] // Array URL foto/video dari Supabase Storage\n}\n\n// 6. Permintaan Material / Alat\nmodel MaterialRequest {\n  id          String         @id @default(uuid())\n  projectId   String\n  project     Project        @relation(fields: [projectId], references: [id])\n  requesterId String\n  requester   User           @relation(fields: [requesterId], references: [id])\n  itemName    String\n  quantity    Float\n  unit        String\n  status      StatusApproval @default(PENDING)\n  createdAt   DateTime       @default(now())\n}\n\n// 7. Pelaporan Kendala (Issue Tracking)\nmodel Issue {\n  id          String        @id @default(uuid())\n  projectId   String\n  project     Project       @relation(fields: [projectId], references: [id])\n  reporterId  String\n  reporter    User          @relation(fields: [reporterId], references: [id])\n  title       String\n  description String\n  severity    IssueSeverity @default(MEDIUM)\n  isResolved  Boolean       @default(false)\n  createdAt   DateTime      @default(now())\n  comments    Comment[]\n}\n\n// 8. Komentar & Diskusi\nmodel Comment {\n  id            String       @id @default(uuid())\n  dailyReportId String?\n  dailyReport   DailyReport? @relation(fields: [dailyReportId], references: [id])\n  issueId       String?\n  issue         Issue?       @relation(fields: [issueId], references: [id])\n  userId        String\n  user          User         @relation(fields: [userId], references: [id])\n  message       String\n  createdAt     DateTime     @default(now())\n}\n\n// 9. Notifikasi\nmodel Notification {\n  id        String   @id @default(uuid())\n  userId    String\n  title     String\n  message   String\n  isRead    Boolean  @default(false)\n  createdAt DateTime @default(now())\n}\n\n// 10. Riwayat Aktivitas (Audit Log)\nmodel ActivityLog {\n  id        String   @id @default(uuid())\n  userId    String\n  user      User     @relation(fields: [userId], references: [id])\n  action    String // Contoh: \"CREATE_DAILY_REPORT\", \"APPROVE_MATERIAL\"\n  details   String\n  createdAt DateTime @default(now())\n}\n",
